# SPDX-License-Identifier: Apache-2.0
"""Generates `Proof/Wg0/Gen/CondPeer.lean`: the strict conditions of the eight peer packs
(`pk394` .. `pk464`), the immediate move `pk474` and the pack `pk476`, from the lemmas of
`Data/StrictPeer.lean`. Run from the repository root."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
K = ROOT / "Kernels/FlashMlaSparseDecodeH64/Proof/Wg0"
HEAD = """-- SPDX-License-Identifier: Apache-2.0
-- Generated by Kernels/FlashMlaSparseDecodeH64/Gen/w0cond_peer_gen.py; do not edit.
-- domain: valid-rows
module

public import Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data.StrictPeer
public import Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Gen.Peer1
public import Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Gen.Peer2

@[expose] public section

namespace PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data
open PTX PTX.Flow PTX.Proof PTX.Assumption PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Gen
  PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0

noncomputable section

"""
SEP = ",\n    "
out = HEAD
for i, pc in enumerate(range(394, 474, 10)):
    r = 2886 + 4 * i
    nc = "cond_of_okVal"
    t = [
        "c_ext h3",
        "c_up h3",
        "c_ext h2",
        "c_ext h1",
        "c_up h1",
        "c_ext h0",
        f"{nc} (pkMlt (by decide) h1 h0) (by intro h; cases h)",
        f"{nc} (pkMge (by decide) h3 h2) (by intro h; cases h)",
        "c_packPair rfl rfl (by decide) (pkMlt (by decide) h1 h0)\n"
        "      (pkMge (by decide) h3 h2)\n"
        "      (halfB_bytes h0) (halfB_bytes h1) (halfB_bytes h2) (halfB_bytes h3)",
        "trivial",
    ]
    hs = "\n    ".join(f"(h{j} : halfB (V {r + j}) = true)" for j in range(4))
    out += (
        f"/-- The condition of the peer pack `pk{pc}`. -/\n"
        f"theorem pk{pc}_cond_of_reads (V : Nat → Value)\n    {hs} :\n"
        f"    xCond (lookupD (pk{pc}_facts0 V)) pk{pc}_items0 := by\n"
        f"  simp only [pk{pc}_items0, xCond]\n  exact ⟨{SEP.join(t)}⟩\n\n"
    )
out += (
    "/-- The condition of `pk474`. -/\ntheorem pk474_cond_of_reads (V : Nat → Value) :\n"
    "    xCond (lookupD (pk474_facts0 V)) pk474_items0 := by\n"
    "  simp only [pk474_items0, xCond]\n"
    "  exact ⟨⟨Value.bits 32 (truncBits 32 64), by\n"
    "    simp [coreF, coreW, pk474_op474, oVal, oBits, DType.width, Value.bytes]; rfl⟩, trivial⟩\n\n"
)
out += (
    "/-- The condition of `pk476`. -/\ntheorem pk476_cond_of_reads (V : Nat → Value)\n"
    "    (h0 : (V 1009).bytes = 4) (h1 : (V 1010).bytes = 4) :\n"
    "    xCond (lookupD (pk476_facts0 V)) pk476_items0 := by\n"
    "  simp only [pk476_items0, xCond]\n  exact ⟨And.intro h0 h1, trivial⟩\n"
)
out += "\nend\nend PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data\n"
(K / "Gen/CondPeer.lean").write_text(out)
